-- Each book's posted tennis retirement rules (Option A), book-rules-2026-11-01.
-- Generated from lib/tennis/log/bookRules.ts (the grader's source of truth); rule codes are defined there.
-- Also adds the progressing player on tennis_matches and the house-rule grade on would-be bets.
-- Idempotent. Rollback: migrations/tennis_book_void_rules_rollback.sql.
BEGIN;
ALTER TABLE public.tennis_matches ADD COLUMN IF NOT EXISTS winner_side TEXT;
ALTER TABLE public.tennis_shadow_bets ADD COLUMN IF NOT EXISTS result_house TEXT;

ON CONFLICT (book, market) DO UPDATE SET
  rule = EXCLUDED.rule,
  unfinished_game_counts = EXCLUDED.unfinished_game_counts,
  super_tiebreak_one_game = EXCLUDED.super_tiebreak_one_game,
  source_url = EXCLUDED.source_url,
  checked_at = EXCLUDED.checked_at,
  notes = EXCLUDED.notes;
COMMIT;
NOTIFY pgrst, 'reload schema';
